window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-16491\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρέω1</h1><div class=\"entry-meta\"><span>DGP · ordem 5252 na letra ε · nº geral 16491</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. jôn. de εἴρω2.</p></section></article>\n<article id=\"entry-dgp-16492\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρέω2</h1><div class=\"entry-meta\"><span>DGP · ordem 5253 na letra ε · nº geral 16492</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 interrogar alguém, ac. 2 perguntar; informar-se sobre algo, ac. 3 procurar alguém 4 explorar algo 5 crist. dar nome; denominar; chamar.</p></section></article>\n<article id=\"entry-dgp-16493\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρήμη, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 5254 na letra ε · nº geral 16493</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἔρημος.</p></section></article>\n<article id=\"entry-dgp-16494\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρημία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5255 na letra ε · nº geral 16494</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lugar ermo, deserto 2 isolamento de uma pessoa; solidão; abandono: ἐρημίαν ἄγειν, ἔχειν eur. viver na solidão 3 desolação; devastação 4 ausência; falta; privação, gen. 〈ἔρημος〉</p></section></article>\n<article id=\"entry-dgp-16495\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔρημος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5256 na letra ε · nº geral 16495</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. ἐρῆμος, η, ον 1 abandonado; inabitado; deserto; desolado (lugar) 2 que vive só; solitário (ser vivo) 3 privado de; desprovido de; separado de, gen. ♦ ἡ ἔρημος ou ἐρήμη 4 o deserto 5 Jur. [δίκη, δίαιτα ou γραφή] processo por contumácia: ἔρημον ὀφλεῖν τὴν δίκην ser condenado por contumácia, ἐρήμην τινὰ λαβεῖν lís. ou ἑλεῖν dem. ganhar um processo por contumácia, ἐρήμην κατηγορεῖν plat. pedir condenação por não-comparecimento ♦ τὰ ἔρημα ou ἐρῆμα 6 a solidão 7 lugares desertos.</p></section></article>\n<article id=\"entry-dgp-16496\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρημόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5257 na letra ε · nº geral 16496</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἠρήμουν, fut. ἐρημώσω, aor. ἠρήμωσα, perf. desus.; pas. aor. ἠρημώθην, perf. ἠρήμωμαι) 1 tornar deserto; tornar vazio; devastar 2 tornar solitário; deixar só 3 manter afastado; isolar 4 desertar; abandonar; deixar um lugar 5 esvaziar de; desguarnecer de; privar algo, ac., de, gen. ou ac.</p></section></article>\n<article id=\"entry-dgp-16497\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρήμωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5258 na letra ε · nº geral 16497</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 despovoamento; devastação 2 desolação. 〈ἐρημόω〉</p></section></article>\n<article id=\"entry-dgp-16498\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρηρέδαται</h1><div class=\"entry-meta\"><span>DGP · ordem 5259 na letra ε · nº geral 16498</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. perf. pas. ép., ἐρηρέδατο 3ª pl. m.-q.-perf. pas. ép., de ἐρείδω.</p></section></article>\n<article id=\"entry-dgp-16499\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρήρεισμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 5260 na letra ε · nº geral 16499</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐρείδω.</p></section></article>\n<article id=\"entry-dgp-16500\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρήριγμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 5261 na letra ε · nº geral 16500</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas. de ἐρείκω.</p></section></article>\n<article id=\"entry-dgp-16501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρήρισμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 5262 na letra ε · nº geral 16501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐρίζω.</p></section></article>\n<article id=\"entry-dgp-16502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρήριμμαι, ἐρηρίμμην</h1><div class=\"entry-meta\"><span>DGP · ordem 5263 na letra ε · nº geral 16502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐρείπω.</p></section></article>\n<article id=\"entry-dgp-16503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 5264 na letra ε · nº geral 16503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de εἴρομαι.</p></section></article>\n<article id=\"entry-dgp-16504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρήτυθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 5265 na letra ε · nº geral 16504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. pas. poét., ἐρητύσασκε 3ª sing. aor. at. iter., de ἐρητύω.</p></section></article>\n<article id=\"entry-dgp-16505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρητύω</h1><div class=\"entry-meta\"><span>DGP · ordem 5266 na letra ε · nº geral 16505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐρήτυον, fut. ἐρητύσω, aor. ἐρήτυσα) 1 manter à distância; manter em um certo lugar; deter; conter 2 manter afastado de; afastar de; impedir de, gen. ♦ méd. 3 deter-se; ficar no lugar; conter-se 4 manter-se à distância de, gen.; manter-se afastado; ficar na retaguarda 5 reter; conter ♦ pas. 6 ser detido 7 ser impedido de, inf.</p></section></article>\n<article id=\"entry-dgp-16506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔρι</h1><div class=\"entry-meta\"><span>DGP · ordem 5267 na letra ε · nº geral 16506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. (τό) = ἔριον.</p></section></article>\n<article id=\"entry-dgp-16507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριαύχην, ην, εν</h1><div class=\"entry-meta\"><span>DGP · ordem 5268 na letra ε · nº geral 16507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ενος de pescoço muito forte; que eleva para muito alto o pescoço (cavalo); que se lança; arqueado. 〈ἐρι-,αὐχήν〉</p></section></article>\n<article id=\"entry-dgp-16508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριβρεμέτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 5269 na letra ε · nº geral 16508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de ruído terrível; de fragor profundo; altissonante. 〈ἐρι-, βρέμω〉</p></section></article>\n<article id=\"entry-dgp-16509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριβῶλαξ, ακος</h1><div class=\"entry-meta\"><span>DGP · ordem 5270 na letra ε · nº geral 16509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) muito fértil; muito fecundo. 〈ἐρι-, βῶλος〉</p></section></article>\n<article id=\"entry-dgp-16510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίβωλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5271 na letra ε · nº geral 16510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐριβῶλαξ.</p></section></article>\n<article id=\"entry-dgp-16511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίγδουπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5272 na letra ε · nº geral 16511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito barulhento; ruidoso; retumbante. 〈ἐρι-, γδοῦπος〉</p></section></article>\n<article id=\"entry-dgp-16512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριδαινέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 5273 na letra ε · nº geral 16512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de ἐριδαίνω.</p></section></article>\n<article id=\"entry-dgp-16513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριδαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 5274 na letra ε · nº geral 16513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. e aor.) 1 disputar com rudeza; entrar em conflito; entrar em luta por, ἕνεκα ou περί e gen., μετά e dat. 2 lutar; combater 3 tard. lutar contra, ac. 〈ἔρις〉</p></section></article>\n<article id=\"entry-dgp-16514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριδάντης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5275 na letra ε · nº geral 16514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">questionador; briguento. 〈ἔρις〉</p></section></article>\n<article id=\"entry-dgp-16515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5276 na letra ε · nº geral 16515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">um pouco de lã. 〈ἔριον〉</p></section></article>\n<article id=\"entry-dgp-16516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριδμαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 5277 na letra ε · nº geral 16516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e aor.) 1 lutar; disputar com rudeza, διά e ac., ὑπέρ e gen. ou inf. 2 causar excitação; excitar; irritar.</p></section></article>\n<article id=\"entry-dgp-16517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίδματος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5278 na letra ε · nº geral 16517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. estabelecido solidamente; inexpugnável. 〈ἐρι-, δέμω〉</p></section></article>\n<article id=\"entry-dgp-16518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίδουπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5279 na letra ε · nº geral 16518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐρίγδουπος.</p></section></article>\n<article id=\"entry-dgp-16519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριζέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 5280 na letra ε · nº geral 16519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἐριζέμεναι inf. pres. ép., ἐρίζεσκον impf. iter., ἔριζον impf. poét., de ἐρίζω.</p></section></article>\n<article id=\"entry-dgp-16520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 5281 na letra ε · nº geral 16520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἤριζον, fut. ἐρίσω, aor. ἤρισα, perf. ἤριχα; perf. pas. ἐρήρισμαι) 1 lutar com; rivalizar com; entrar em disputa com; contender alguém, dat. ou πρός e ac., em algo, ac., dat. ou ἀμφί e dat., περί e gen. 2 Filos. (sofista) discutir; altercar 3 afirmar rispidamente; sustentar com rudeza ou obstinadamente, inf. ♦ méd. 4 combater alguém, dat.</p></section></article>\n<article id=\"entry-dgp-16521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίηρες, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5282 na letra ε · nº geral 16521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito ligados; muito fiéis: ἐρίηρας ἑταίρους hom. fiéis companheiros.</p></section></article>\n<article id=\"entry-dgp-16522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίηρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5283 na letra ε · nº geral 16522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estreitamente unido 2 afeiçoado; fiel (amigo). 〈ἐρι-, ἄρω〉</p></section></article>\n<article id=\"entry-dgp-16523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριθεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5284 na letra ε · nº geral 16523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 subterfúgio; manobra 2 intriga 3 rivalidade; disputa. 〈ἐριθεύω〉</p></section></article>\n<article id=\"entry-dgp-16524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριθεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 5285 na letra ε · nº geral 16524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trabalhar por salário ou como mercenário 2 (mulher) fiar 3 trabalhar ♦ méd. 4 usar de subterfúgios, de manobras.</p></section></article>\n<article id=\"entry-dgp-16525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριθηλής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5286 na letra ε · nº geral 16525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 florescente; florido; viçoso 2 fecundo; fértil. 〈θάλλω〉</p></section></article>\n<article id=\"entry-dgp-16526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔριθος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5287 na letra ε · nº geral 16526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trabalhador assalariado 2 ceifador; lavrador 3 servo 4 fem. serva; fiandeira; tecelã.</p></section></article>\n<article id=\"entry-dgp-16527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίκη</h1><div class=\"entry-meta\"><span>DGP · ordem 5288 na letra ε · nº geral 16527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐρείκη.</p></section></article>\n<article id=\"entry-dgp-16528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρικυδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5289 na letra ε · nº geral 16528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito famoso; glorioso 2 esplêndido; magnífico. 〈ἐρι-, κῦδος〉</p></section></article>\n<article id=\"entry-dgp-16529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρικύμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5290 na letra ε · nº geral 16529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος 1 muito fecundo; muito fértil 2 prenhe (lebre). 〈ἐρι-, κύω〉</p></section></article>\n<article id=\"entry-dgp-16530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίμυκος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5291 na letra ε · nº geral 16530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de mugidos fortes. 〈ἐρι-, μυκάομαι〉</p></section></article>\n<article id=\"entry-dgp-16531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρινεός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5292 na letra ε · nº geral 16531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 figueira selvagem 2 figo selvagem. 〈ἐρινός〉</p></section></article>\n<article id=\"entry-dgp-16532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίνεος,</h1><div class=\"entry-meta\"><span>DGP · ordem 5293 na letra ε · nº geral 16532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. εἰρίνεος, η, ον de lã. 〈ἔριον〉</p></section></article>\n<article id=\"entry-dgp-16533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρινός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5294 na letra ε · nº geral 16533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 figo selvagem 2 figueira selvagem.</p></section></article>\n<article id=\"entry-dgp-16534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐρινύς, ύος</h1><div class=\"entry-meta\"><span>DGP · ordem 5295 na letra ε · nº geral 16534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. pl. Ἐρινύας e Ἐρινῦς (ἡ) 1 Erínia, pl. Erínias, Tisífone, Megera e Alecto, deusas da vingança, punem o perjúrio ou a injúria contra parentes e hóspedes 2 castigo invocado contra o culpado 3 maldição vingadora; vingança 4 flagelo vingador (pessoa) 5 desvario resultante de vingança divina 6 Erínia, epít. de Deméter.</p></section></article>\n<article id=\"entry-dgp-16535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρινυώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 5296 na letra ε · nº geral 16535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante às Erínias. 〈Ἐρινύς, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-16536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔριον,</h1><div class=\"entry-meta\"><span>DGP · ordem 5297 na letra ε · nº geral 16536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e ép. εἴριον, ου (τό) 1 lã 2 algodão 3 filamento lanoso de concha do mar 4 fio ou teia de aranha. 〈ἔρος〉</p></section></article>\n<article id=\"entry-dgp-16537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριόστεπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5298 na letra ε · nº geral 16537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">coroado de lã. 〈ἔριον, στέφω〉</p></section></article>\n<article id=\"entry-dgp-16538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριούνης</h1><div class=\"entry-meta\"><span>DGP · ordem 5299 na letra ε · nº geral 16538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἐριούνιος, ου (ὁ) o que socorre; o benfazejo, epít. de Hermes. 〈ἐρι-, ὀνίνημι〉</p></section></article>\n<article id=\"entry-dgp-16539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριουργέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 5300 na letra ε · nº geral 16539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">trabalhar a lã. 〈ἔριον, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-16540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίπῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 5301 na letra ε · nº geral 16540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἐρείπω.</p></section></article>\n<article id=\"entry-dgp-16541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔρις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 5302 na letra ε · nº geral 16541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. ἔριν ou ἔριδα, n. pl. ἔριδες e, bíbl., ἔρεις (ἡ) 1 falta de união; discórdia; disputa acirrada; contestação; luta 2 luta armada; disputa de guerra; combate 3 rivalidade; emulação ♦ ἡ Ἔρις 4 Éris, Querela ou Discórdia, divindade.</p></section></article>\n<article id=\"entry-dgp-16542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρισθενής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 5303 na letra ε · nº geral 16542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito forte; muito poderoso. 〈ἐρι-, σθένος〉</p></section></article>\n<article id=\"entry-dgp-16543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίσκηπτρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5304 na letra ε · nº geral 16543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἐρυσίσκεπτρον.</p></section></article>\n<article id=\"entry-dgp-16544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔρισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5305 na letra ε · nº geral 16544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">objeto de disputa. 〈ἐρίζω〉</p></section></article>\n<article id=\"entry-dgp-16545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρισμάραγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5306 na letra ε · nº geral 16545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de grande ruído; fragoroso. 〈ἐρι-, σμάραγος〉</p></section></article>\n<article id=\"entry-dgp-16546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίσσειε</h1><div class=\"entry-meta\"><span>DGP · ordem 5307 na letra ε · nº geral 16546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. opt. aor., ἐρίσσεται 3ª sing. fut. méd. ou 3ª sing. subj. aor. méd. ép., ἐρίσσομαι fut. méd. ép., de ἐρίζω.</p></section></article>\n<article id=\"entry-dgp-16547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριστάφυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5308 na letra ε · nº geral 16547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 produzido com boas uvas (vinho) 2 rico de boas uvas. 〈ἐρι-, σταφυλή〉</p></section></article>\n<article id=\"entry-dgp-16548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5309 na letra ε · nº geral 16548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dado à discussão; amigo de contendas 2 que comporta discussão ♦ ἡ ἐριστική ou τὸ ἐριστικόν ou τὰ ἐριστικά 3 a arte de discutir 4 hábito de discutir ♦ οἱ ἐριστικοί tard. 5 os filósofos erísticos. 〈ἐριστός〉</p></section></article>\n<article id=\"entry-dgp-16549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐριστός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5310 na letra ε · nº geral 16549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sujeito a discussão; discutível 2 que se pode disputar com alguém, dat. 〈ἐρίζω〉</p></section></article>\n<article id=\"entry-dgp-16550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρισφάραγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5311 na letra ε · nº geral 16550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de voz retumbante.</p></section></article>\n<article id=\"entry-dgp-16551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίτιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5312 na letra ε · nº geral 16551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muito precioso ♦ ὁ, ἡ ἐρίτιμος 2 tipo de peixe, talvez sardinha. 〈ἐρι-, τιμή〉</p></section></article>\n<article id=\"entry-dgp-16552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίφειος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5313 na letra ε · nº geral 16552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de cabrito. 〈ἔριφος〉</p></section></article>\n<article id=\"entry-dgp-16553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐρίφιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5314 na letra ε · nº geral 16553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cabritinho. 〈ἔριφος〉</p></section></article>\n<article id=\"entry-dgp-16554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔριφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5315 na letra ε · nº geral 16554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cabrito 2 pl. Cabritos, constelação.</p></section></article>\n<article id=\"entry-dgp-16555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρκεῖος,</h1><div class=\"entry-meta\"><span>DGP · ordem 5316 na letra ε · nº geral 16555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ἕρκειος, tard. ἕρκιος, ος e α, ον 1 referente aos muros de um recinto; da cerca; do muro; do valado; do muro exterior; do recinto fechado: πύλαι ἕρκειοι cancela, ἑρ. θύρα porta externa, ἑρ. στέγη sóf. teto de uma tenda 2 protetor do recinto, epít. de Zeus, protetor da casa e cujo altar ficava no pátio; ἕρκιοι θεοί d.h. deuses penates, em Roma. 〈ἕρκος〉</p></section></article>\n<article id=\"entry-dgp-16556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρκίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5317 na letra ε · nº geral 16556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cerca; muro externo 2 recinto; casa; habitação. 〈ἕρκος〉</p></section></article>\n<article id=\"entry-dgp-16557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕρκιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5318 na letra ε · nº geral 16557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἑρκεῖος.</p></section></article>\n<article id=\"entry-dgp-16558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕρκος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5319 na letra ε · nº geral 16558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 muro; cerca; barreira 2 recinto interno 3 muralha (formada por armas, escudos) 4 barreira; dique; defesa 5 proteção: ἕρ. βελέων hom. proteção contra setas, ἕρ. πολέμοιο hom. muralha de guerra 6 armadilha; rede (de caça e pesca) 7 trama; intriga 8 fechamento; defesa; proteção: ἕρ. ὀδόντων hom. barreira dos dentes. 〈εἴργω〉</p></section></article>\n<article id=\"entry-dgp-16559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕρμα1, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5320 na letra ε · nº geral 16559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escora para prender navio na praia 2 ponto de apoio; fundamento; esteio 3 base; causa; origem 4 rochedo; escolho 5 monte de terra ou de ruínas 6 lastro de navio 7 contrapeso para equilíbrio de vôo (de aves, insetos) 8 fardo, ref. ao feto no ventre da mãe.</p></section></article>\n<article id=\"entry-dgp-16560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕρμα2, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5321 na letra ε · nº geral 16560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pingente de orelha; brinco 2 colar. ῾Ερμάδιον, ου (τό) pequeno Hermes. 〈 Ἑρμῆς〉 ῾Ερμαῖα, ων (τά) cf. Ἑρμαῖος.</p></section></article>\n<article id=\"entry-dgp-16561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἕρμαιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5322 na letra ε · nº geral 16561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feliz achado propiciado por Hermes; ganho inesperado; grata surpresa; golpe de sorte.</p></section></article>\n<article id=\"entry-dgp-16562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 5323 na letra ε · nº geral 16562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Hermes; consagrado ou dedicado a Hermes 2 dado por Hermes; vindo de Hermes 3 proveitoso; vantajoso ♦ τὰ Ἑρμαῖα 4 festas de Hermes 5 competições de efebos presididas por Hermes. 〈 Ἑρμῆς〉</p></section></article>\n<article id=\"entry-dgp-16563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμᾶς</h1><div class=\"entry-meta\"><span>DGP · ordem 5324 na letra ε · nº geral 16563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = Ἑρμῆς.</p></section></article>\n<article id=\"entry-dgp-16564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμαφρόδιτος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5325 na letra ε · nº geral 16564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Hermafrodita, filho de Hermes e Afrodite 2 hermafrodita; andrógino. 〈 Ἑρμῆς, Ἀφροδίτη〉</p></section></article>\n<article id=\"entry-dgp-16565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμέας</h1><div class=\"entry-meta\"><span>DGP · ordem 5326 na letra ε · nº geral 16565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. e jôn. = Ἑρμῆς.</p></section></article>\n<article id=\"entry-dgp-16566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμέης, έω</h1><div class=\"entry-meta\"><span>DGP · ordem 5327 na letra ε · nº geral 16566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Ἑρμῆς.</p></section></article>\n<article id=\"entry-dgp-16567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμείας</h1><div class=\"entry-meta\"><span>DGP · ordem 5328 na letra ε · nº geral 16567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = Ἑρμῆς.</p></section></article>\n<article id=\"entry-dgp-16568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμείης, είω</h1><div class=\"entry-meta\"><span>DGP · ordem 5329 na letra ε · nº geral 16568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. e jôn. = Ἑρμῆς.</p></section></article>\n<article id=\"entry-dgp-16569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμέω</h1><div class=\"entry-meta\"><span>DGP · ordem 5330 na letra ε · nº geral 16569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. Ἑρμέης.</p></section></article>\n<article id=\"entry-dgp-16570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμῆ</h1><div class=\"entry-meta\"><span>DGP · ordem 5331 na letra ε · nº geral 16570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. Ἑρμῆς.</p></section></article>\n<article id=\"entry-dgp-16571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμηνεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5332 na letra ε · nº geral 16571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 interpretação; explicação 2 expressão; tradução 3 modo de exposição; estilo. 〈ἑρμηνεύς〉</p></section></article>\n<article id=\"entry-dgp-16572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμήνευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5333 na letra ε · nº geral 16572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 interpretação; explicação 2 significado; símbolo 3 monumento. 〈ἑρμηνεύω〉</p></section></article>\n<article id=\"entry-dgp-16573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμηνεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5334 na letra ε · nº geral 16573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que explica; expositor; intérprete 2 tradutor. 〈ἑρμηνεύω〉</p></section></article>\n<article id=\"entry-dgp-16574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμηνευτής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5335 na letra ε · nº geral 16574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἑρμηνεύς.</p></section></article>\n<article id=\"entry-dgp-16575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμηνευτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 5336 na letra ε · nº geral 16575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que interpreta 2 referente à interpretação; próprio para fazer compreender: ἑρμηνευτικὴ δύναμις luc. força expressiva ♦ ἡ ἑρμηνευτική 3 arte da interpretação. 〈ἑρμηνεύω〉</p></section></article>\n<article id=\"entry-dgp-16576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμηνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 5337 na letra ε · nº geral 16576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἡρμήνευον, aor. ἡρμήνευσα) 1 expressar (pensamentos, fatos); dar a conhecer; expor; explicar 2 articular bem; falar 3 fazer compreender; interpretar 4 traduzir (de uma língua) ♦ méd. 5 expor 6 dar informação ♦ pas. 7 receber uma explicação.</p></section></article>\n<article id=\"entry-dgp-16577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμῆς, οῦ,</h1><div class=\"entry-meta\"><span>DGP · ordem 5338 na letra ε · nº geral 16577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">voc. -ῆ (ὁ) 1 Hermes, filho de Zeus e de Maia, mensageiro dos deuses, protetor do comércio e das viagens 2 herma, objeto de veneração e com valor simbólico, consistia em busto ou cabeça de Hermes colocado sobre uma coluna nas praças, ruas, caminhos, nos limites das propriedades, indicando a direção a seguir 3 Astron. Hermes ou Mercúrio, planeta.</p></section></article>\n<article id=\"entry-dgp-16578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμίν</h1><div class=\"entry-meta\"><span>DGP · ordem 5339 na letra ε · nº geral 16578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἑρμίς.</p></section></article>\n<article id=\"entry-dgp-16579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμιόνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5340 na letra ε · nº geral 16579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Hermione, n. de mulher, partic. da filha de Menelau e Helena.</p></section></article>\n<article id=\"entry-dgp-16580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμίς</h1><div class=\"entry-meta\"><span>DGP · ordem 5341 na letra ε · nº geral 16580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἑρμίν, ῖνος (ὁ) pé da cama. 〈ἕρμα1〉</p></section></article>\n<article id=\"entry-dgp-16581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμογένης, ους (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5342 na letra ε · nº geral 16581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Hermógenes, n. de homem.</p></section></article>\n<article id=\"entry-dgp-16582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμογλυφεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5343 na letra ε · nº geral 16582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 escultor de hermas 2 estatuário. 〈Ἐρμῆς, γλύφω〉</p></section></article>\n<article id=\"entry-dgp-16583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἑρμογλύφαι, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5344 na letra ε · nº geral 16583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a rua das estatuárias, em Atenas.</p></section></article>\n<article id=\"entry-dgp-16584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμογλυφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5345 na letra ε · nº geral 16584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arte da estatuária. 〈ἑρμογλύφος〉</p></section></article>\n<article id=\"entry-dgp-16585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμογλυφική, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5346 na letra ε · nº geral 16585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arte da estatuária. 〈ἑρμογλύφος〉</p></section></article>\n<article id=\"entry-dgp-16586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμογλύφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5347 na letra ε · nº geral 16586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">escultor.</p></section></article>\n<article id=\"entry-dgp-16587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑρμοκοπίδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5348 na letra ε · nº geral 16587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mutilador das hermas. 〈 Ἑρμῆς, κόπτω〉</p></section></article>\n<article id=\"entry-dgp-16588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἕρμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 5349 na letra ε · nº geral 16588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Hermos, filho de Oceano e n. de rio da Frígia.</p></section></article>\n<article id=\"entry-dgp-16589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔρνος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 5350 na letra ε · nº geral 16589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 broto; galho novo; planta nova 2 novo ramo; descendente.</p></section></article>\n<article id=\"entry-dgp-16590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔρξα</h1><div class=\"entry-meta\"><span>DGP · ordem 5351 na letra ε · nº geral 16590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἔρδω.</p></section></article>\n";
